import { Repository,STATUSES,PRIORITIES,TYPES,filterIssues,csvValue,DEMO_KEY } from './data.js';
import { SUPABASE_URL } from './config.js';
const $=s=>document.querySelector(s);
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',folder:'M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z',issues:'M9 6h11 M9 12h11 M9 18h11 M3 6h1 M3 12h1 M3 18h1',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',activity:'M3 12h4l3-8 4 16 3-8h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M19 5l-2 2 M7 17l-2 2',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',plus:'M12 5v14 M5 12h14',search:'M21 21l-5-5 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',arrow:'M4 12h16 M14 6l6 6-6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',logout:'M9 4H4v16h5 M9 12h12 M16 7l5 5-5 5',more:'M5 12h.01 M12 12h.01 M19 12h.01',bug:'M8 8h8v8a4 4 0 0 1-8 0Z M9 8V6a3 3 0 0 1 6 0v2 M4 10h4 M16 10h4 M4 15h4 M16 15h4 M6 21l3-3 M18 21l-3-3 M12 9v9',check:'m5 12 4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',flag:'M5 21V3 M5 3c5-4 9 4 14 0v10c-5 4-9-4-14 0',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',close:'M6 6l12 12 M6 18 18 6',edit:'m15 5 4 4 M4 20l1-6L16 3l5 5-11 11Z',link:'m10 13 4-4 M8 15l-2 2a3 3 0 0 1-4-4l5-5a3 3 0 0 1 4 0 M16 9l2-2a3 3 0 0 1 4 4l-5 5a3 3 0 0 1-4 0',image:'M3 3h18v18H3z m0 14 5-5 4 4 3-3 6 6 M15 7h.01',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',board:'M3 4h18v16H3z M9 4v16 M15 4v16',menu:'M4 6h16 M4 12h16 M4 18h16',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z m-4 9 3 3 5-6',up:'m7 14 5-5 5 5 M7 19l5-5 5 5',minus:'M5 12h14',external:'M14 3h7v7 M10 14 11-11 M21 14v7H3V3h7',mail:'M3 5h18v14H3z m0 0 9 7 9-7',archive:'M3 3h18v5H3z M5 8v13h14V8 M10 12h4'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.issues}"/></svg>`;
const brand=()=>'<div class="brand"><span class="brand-icon">g.</span><div class="brand-name">GNITS_develop<small>BUILD BETTER, TOGETHER</small></div></div>';
let repo=new Repository(),data={profiles:[],projects:[],issues:[],project_members:[],activity:[],notifications:[]},me=null,view='dashboard',filters={project:'',status:'',priority:'',type:'',search:'',mine:false},issueView='list',page=1,detailTab='discussion',detailId=null,refreshTimer,modalToken=0,lastFocus;
const admin=()=>me?.role==='admin';
const developer=()=>['admin','developer'].includes(me?.role);
const project=id=>data.projects.find(p=>p.id===id);
const person=id=>data.profiles.find(p=>p.id===id);
const name=id=>person(id)?.full_name||'Former member';
const issueKey=i=>`${project(i.project_id)?.prefix||'ISS'}-${String(i.issue_no).padStart(3,'0')}`;
const date=v=>new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short'}).format(new Date(v));
const time=v=>{const mins=Math.max(0,Math.floor((Date.now()-new Date(v))/60000));return mins<1?'Just now':mins<60?`${mins}m ago`:mins<1440?`${Math.floor(mins/60)}h ago`:`${Math.floor(mins/1440)}d ago`;};
const initials=value=>String(value||'?').trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase();
const avatar=(id,small=false)=>`<span class="avatar ${small?'small':''}" title="${esc(name(id))}">${esc(initials(name(id)))}</span>`;
const slug=s=>s.toLowerCase().replaceAll(' ','-');
const statusBadge=s=>`<span class="badge ${slug(s)}">${esc(s)}</span>`;
const priorityBadge=p=>`<span class="priority ${p.toLowerCase()}">${icon(p==='Low'?'down':p==='Medium'?'minus':'up')}${esc(p)}</span>`;
const typeIcon=t=>icon(t==='Bug'?'bug':t==='Feature'?'spark':'edit');
const button=(label,action,style='',extra='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${extra}>${label}</button>`;
const options=(values,value,empty)=>`${empty!==undefined?`<option value="">${esc(empty)}</option>`:''}${values.map(v=>{const [key,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(key)}" ${String(key)===String(value)?'selected':''}>${esc(label)}</option>`;}).join('')}`;
const empty=(title,copy,action='')=>`<div class="empty">${icon('folder')}<h3>${esc(title)}</h3><p>${esc(copy)}</p>${action}</div>`;
function toast(message,error=false){$('#toast-root').innerHTML=`<div class="toast ${error?'error':''}">${esc(message)}</div>`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast-root').innerHTML='',6500);}
function errorText(error){if(error?.code==='42P01'||error?.code==='PGRST205')return 'The database is not set up yet. Open the setup guide and run the supplied SQL file.';return error?.message||'Something went wrong. Please try again.';}
function errorAt(form,error){const el=form.querySelector('.form-error');if(el){el.textContent=errorText(error);el.scrollIntoView({block:'nearest'});}else toast(errorText(error),true);}
function loginScreen(message=''){
 me=null;$('#app').innerHTML=`<main class="login"><section class="login-art">${brand()}<div class="login-art-copy"><div class="eyebrow">ONE WORKSPACE. EVERY PROJECT.</div><h1>Good products<br>start with<br><em>better feedback.</em></h1><p>Give every issue a home. Keep your testers, developers, and next big release in sync.</p><div class="floating-card"><div class="floating-card-top"><span class="stat-icon">${icon('check')}</span><div><h3>Another fix, verified.</h3><p>Small improvements. Better experiences.</p></div></div><div class="floating-card-bottom">${statusBadge('Closed')}<span class="avatar-group"><span class="avatar small">AR</span><span class="avatar small">RK</span><span class="avatar small">SR</span></span></div></div></div><div class="login-art-footer">A little clarity. A lot of progress.</div></section><section class="login-form-wrap"><div class="login-form"><div class="eyebrow">WELCOME TO GNITS_DEVELOP</div><h2>Your next great release<br>starts here.</h2><p>Sign in with the credentials provided by your administrator.</p><form data-form="login"><div class="form-error" role="alert">${esc(message)}</div><div class="field"><label for="identifier">Email or username</label><input id="identifier" name="identifier" type="text" placeholder="Your email or username" autocomplete="username" autocapitalize="none" spellcheck="false" required></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" placeholder="Enter your password" autocomplete="current-password" required></div><button class="btn primary" type="submit">Sign in to workspace ${icon('arrow')}</button></form><div class="divider">TAKE A LOOK AROUND</div>${button('Explore demo workspace '+icon('arrow'),'demo','')}<p class="login-small">Demo changes stay in this browser.<br>Live project data is only available after signing in.</p><div class="login-links"><button class="text-button" data-action="setup">First-time setup</button><button class="text-button" data-action="login-help">Need access?</button></div></div></section></main>`;
}
async function load(){data=await repo.load();const profile=data.profiles.find(p=>p.id===repo.user.id);if(!profile||!profile.active){throw new Error(profile?'Your account is disabled. Contact your administrator.':'Your account profile is missing. Complete the database setup or ask your administrator.');}me=profile;}
async function enter(){await load();render();route();repo.subscribe(()=>{clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>refresh().catch(e=>toast(errorText(e),true)),500);});}
async function refresh(){await load();render();}
function navButton(label,id,ico,count=''){return `<button data-action="navigate" data-view="${id}" class="${view===id?'active':''}">${icon(ico)}${label}${count?`<span class="nav-count">${count}</span>`:''}</button>`;}
function render(){
 if(!me)return;
 const unread=data.notifications.filter(n=>!n.read_at).length;
 const titles={dashboard:'Overview',projects:'Projects',issues:'All issues',team:'Team members',activity:'Activity',notifications:'Notifications',settings:'Settings'};
 $('#app').innerHTML=`<aside class="sidebar">${brand()}<div class="workspace-label">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${navButton('Overview','dashboard','grid')}${navButton('Projects','projects','folder')}${navButton('All issues','issues','issues',data.issues.filter(i=>i.status!=='Closed').length)}${navButton(admin()?'Team members':'Project members','team','users')}${navButton('Activity','activity','activity')}</nav><div class="side-projects"><div class="workspace-label">YOUR PROJECTS</div>${data.projects.filter(p=>!p.archived).slice(0,5).map(p=>`<button class="side-project" data-action="project-issues" data-id="${p.id}"><span class="project-dot" style="background:${safeColor(p.color)}"></span>${esc(p.name)}</button>`).join('')||'<p class="hint" style="padding-left:15px">Your projects will appear here.</p>'}</div><div class="side-bottom"><div class="side-note"><span class="sparkle">${icon('spark')}</span><p>Every little fix makes<br>a big difference.</p></div><nav class="nav" aria-label="Account">${navButton('Settings','settings','settings')}</nav><div class="profile">${avatar(me.id)}<div class="profile-text"><strong>${esc(me.full_name)}</strong><span>${esc(me.role)}</span></div><button class="icon-button" data-action="logout" aria-label="Sign out" title="Sign out">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb"><span>Workspace</span>${icon('chevron')}<strong>${titles[view]}</strong></div><div class="header-actions"><form class="search-wrap" data-form="search">${icon('search')}<input name="search" id="global-search" aria-label="Search issues" placeholder="Search anything…"><kbd class="keycap">⌘ K</kbd></form><button class="icon-button" data-action="navigate" data-view="notifications" aria-label="Notifications${unread?`, ${unread} unread`:''}">${icon('bell')}${unread?'<span class="notification-dot"></span>':''}</button><button class="icon-button" data-action="navigate" data-view="settings" aria-label="Account settings">${avatar(me.id,true)}</button></div></header>${repo.demo?'<div class="demo-banner"><span>DEMO WORKSPACE · Sample data, saved only in this browser</span><button data-action="logout">Go to live sign-in →</button></div>':''}<div class="content">${({dashboard:dashboard,projects:projectsPage,issues:issuesPage,team:teamPage,activity:activityPage,notifications:notificationsPage,settings:settingsPage}[view]||dashboard)()}<footer class="footer-note"><span>GNITS_develop · Made for better releases.</span><span><i class="live-dot"></i>${repo.demo?'Demo workspace':'Supabase workspace'}</span></footer></div></main>`;
}
function safeColor(v){return /^#[0-9a-f]{6}$/i.test(v)?v:'#7860dc';}
function heading(title,subtitle,actions='',eyebrow='YOUR WORKSPACE, AT A GLANCE'){return `<div class="welcome-row"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function dashboard(){
 const issues=data.issues,open=issues.filter(i=>i.status!=='Closed'),closed=issues.length-open.length,ready=issues.filter(i=>i.status==='Ready for testing').length,critical=open.filter(i=>i.priority==='Critical').length;
 const rate=issues.length?Math.round(closed/issues.length*100):0;
 return heading(`Hello, ${esc(me.full_name.split(' ')[0])}<em>.</em>`,"Here’s what’s happening across your projects today.",button(icon('download')+' Export issues','export')+button(icon('plus')+' Report an issue','new-issue','primary'))+`<section class="stats" aria-label="Workspace statistics">${[['Total issues',issues.length,'issues',`${data.projects.filter(p=>!p.archived).length} active projects`],['Open issues',open.length,'flag',`${critical} critical ${critical===1?'issue needs':'issues need'} attention`],['Ready for testing',ready,'clock','Your next fixes to verify'],['Resolved issues',closed,'check',`${rate}% of all issues resolved`]].map(([label,n,ico,sub],index)=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${String(n).padStart(2,'0')}</div><div class="stat-bottom">${index===3?'<span class="good">'+icon('check').replace('class="icon"','class="icon" style="width:10px;height:10px"')+'</span>':''}${sub}</div></div>`).join('')}</section><section><div class="section-heading"><h2>Your projects <span class="heading-count">${data.projects.filter(p=>!p.archived).length}</span></h2><button class="text-button" data-action="navigate" data-view="projects">View all projects ${icon('arrow')}</button></div><div class="project-grid">${data.projects.filter(p=>!p.archived).slice(0,3).map(projectCard).join('')||empty('A fresh start','Create your first project to give your reports a home.',admin()?button(icon('plus')+' Create project','new-project','primary'):'')}</div></section><section class="dashboard-bottom"><div class="panel"><div class="section-heading panel-heading"><h2>Recent issues</h2><button class="text-button" data-action="navigate" data-view="issues">View all ${icon('arrow')}</button></div>${issueTable([...issues].sort((a,b)=>new Date(b.updated_at)-new Date(a.updated_at)).slice(0,5),true)}<div class="table-footer"><span>Latest updates across your projects</span><span>${issues.length} total issues</span></div></div><aside class="panel"><div class="section-heading panel-heading"><h2>Recent activity</h2>${icon('activity')}</div><div class="activity-list">${activityItems([...data.activity].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).slice(0,4))}</div></aside></section>`;
}
function projectCard(p){const list=data.issues.filter(i=>i.project_id===p.id),closed=list.filter(i=>i.status==='Closed').length,progress=list.length?Math.round(closed/list.length*100):0,members=data.project_members.filter(m=>m.project_id===p.id);return `<article class="project-card" style="--project-color:${safeColor(p.color)}"><div class="project-card-top"><span class="project-logo">${esc(initials(p.name))}</span>${admin()?`<button class="icon-button" data-action="edit-project" data-id="${p.id}" aria-label="Manage ${esc(p.name)}">${icon('more')}</button>`:p.archived?'<span class="pill">Archived</span>':icon('folder')}</div><button class="project-name" data-action="project-issues" data-id="${p.id}">${esc(p.name)}</button>${p.archived?'<span class="pill">Archived</span>':''}<p>${esc(p.description||'Your team’s next great release.')}</p><div class="project-progress-label"><span>Issue resolution</span><strong>${progress}%</strong></div><div class="progress-track" role="progressbar" aria-label="${esc(p.name)} resolution" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}"><span style="width:${progress}%"></span></div><div class="project-footer"><div class="avatar-group">${members.slice(0,3).map(m=>avatar(m.user_id,true)).join('')}${members.length>3?`<span class="avatar small">+${members.length-3}</span>`:''}${!members.length?'<span>No members yet</span>':''}</div><span><b>${list.length-closed}</b> open · ${list.length} total</span></div></article>`;}
function projectsPage(){return heading('A home for every <em>project.</em>','Keep your apps, people, and reports neatly connected.',admin()?button(icon('plus')+' New project','new-project','primary'):'','YOUR PROJECTS')+`<div class="project-grid all-projects">${data.projects.map(projectCard).join('')||empty('No projects yet',admin()?'Create a project and assign your testers.':'Your administrator will assign you to a project.',admin()?button('Create project','new-project','primary'):'')}</div>`;}
function issueTable(list,compact=false){if(!list.length)return empty('Nothing here yet','Try changing your filters or report the first issue.');return `<div class="table-scroll"><table><thead><tr><th>Issue</th>${compact?'':'<th>Project</th>'}<th>Status</th><th>Priority</th><th>Assignee</th>${compact?'':'<th>Updated</th>'}</tr></thead><tbody>${list.map(i=>`<tr><td><div class="issue-cell"><span class="issue-type" title="${i.type}">${typeIcon(i.type)}</span><button class="issue-title" data-action="open-issue" data-id="${i.id}">${esc(i.summary)}<span class="issue-id">${esc(issueKey(i))}</span></button></div></td>${compact?'':`<td><span class="muted">${esc(project(i.project_id)?.name)}</span></td>`}<td>${statusBadge(i.status)}</td><td>${priorityBadge(i.priority)}</td><td>${i.assignee_id?avatar(i.assignee_id,true):'<span class="muted">—</span>'}</td>${compact?'':`<td class="muted">${date(i.updated_at)}</td>`}</tr>`).join('')}</tbody></table></div>`;}
function issuesPage(){const p=project(filters.project);let list=filtered();const pages=Math.max(1,Math.ceil(list.length/15));page=Math.min(page,pages);return heading(p?`${esc(p.name)}<em>.</em>`:'Every issue. <em>One place.</em>',p?esc(p.description):'From the first report to the final verification.',button(icon('download')+' Export','export')+button(icon('plus')+' Report an issue','new-issue','primary'),'ISSUE TRACKER')+`<div class="filters"><input id="issue-search" aria-label="Search reports" data-filter="search" placeholder="Search issues…" value="${esc(filters.search)}"><select aria-label="Filter project" data-filter="project">${options(data.projects.map(p=>[p.id,p.name]),filters.project,'All projects')}</select><select aria-label="Filter status" data-filter="status">${options(STATUSES,filters.status,'All statuses')}</select><select aria-label="Filter priority" data-filter="priority">${options(PRIORITIES,filters.priority,'All priorities')}</select><select aria-label="Filter issue type" data-filter="type">${options(TYPES,filters.type,'All types')}</select><label class="check-filter"><input type="checkbox" data-filter="mine" ${filters.mine?'checked':''}>Assigned to me</label><div class="view-toggle"><button data-action="issue-view" data-value="list" class="${issueView==='list'?'active':''}">${icon('issues')}List</button><button data-action="issue-view" data-value="board" class="${issueView==='board'?'active':''}">${icon('board')}Board</button></div>${Object.values(filters).some(Boolean)?'<button class="text-button" data-action="clear-filters">Clear filters</button>':''}</div>${issueView==='board'?board(list):`<div class="panel">${issueTable(list.slice((page-1)*15,page*15))}<div class="table-footer"><span>${list.length?((page-1)*15+1)+'–'+Math.min(page*15,list.length):0} of ${list.length} issues</span><div class="actions">${button('Previous','prev','small',page===1?'disabled':'')}<span>${page} / ${pages}</span>${button('Next','next','small',page===pages?'disabled':'')}</div></div></div>`}`;}
function filtered(){return filterIssues(data.issues,filters,me.id).sort((a,b)=>new Date(b.updated_at)-new Date(a.updated_at));}
function board(list){return `<div class="board">${STATUSES.map(s=>{const items=list.filter(i=>i.status===s);return `<section class="board-column"><div class="board-heading">${statusBadge(s)}<span>${items.length}</span></div>${items.map(i=>`<article class="board-card"><div class="issue-id">${esc(issueKey(i))}</div><button class="issue-title" data-action="open-issue" data-id="${i.id}">${esc(i.summary)}</button><div class="board-card-footer">${priorityBadge(i.priority)}${i.assignee_id?avatar(i.assignee_id,true):'<span class="hint">Unassigned</span>'}</div></article>`).join('')||'<div class="hint" style="padding:18px 4px;text-align:center">No issues here</div>'}</section>`;}).join('')}</div>`;}
function teamPage(){return heading(admin()?'The people behind <em>the progress.</em>':'Your project <em>team.</em>',admin()?'Create accounts and give everyone the right access.':'Meet the people working on your projects.',admin()?button(icon('plus')+' Create account','new-user','primary'):'','TEAM & ACCESS')+`<div class="panel"><div class="table-scroll"><table><thead><tr><th>Member</th><th>Role</th><th>Projects</th><th>Status</th>${admin()?'<th>Manage</th>':''}</tr></thead><tbody>${data.profiles.map(u=>`<tr><td><div class="member-row">${avatar(u.id)}<div><strong>${esc(u.full_name)}</strong><div class="hint">${esc(u.email)}${u.username?" · @"+esc(u.username):""}</div></div></div></td><td><span class="tag">${esc(u.role)}</span></td><td>${u.role==='admin'?'<span class="hint">All projects</span>':data.project_members.filter(m=>m.user_id===u.id).map(m=>`<span class="tag" style="margin:2px">${esc(project(m.project_id)?.name)}</span>`).join('')||'<span class="hint">No projects assigned</span>'}</td><td>${u.active?'<span class="badge closed">Active</span>':'<span class="badge archived">Disabled</span>'}</td>${admin()?`<td><div class="team-actions">${button('Manage','edit-user','small',`data-id="${u.id}"`)}</div></td>`:''}</tr>`).join('')}</tbody></table></div></div>`;}
function activityItems(list){return list.map(a=>{const i=data.issues.find(i=>i.id===a.issue_id);return `<div class="activity-item">${avatar(a.actor_id,true)}<div class="activity-copy"><strong>${esc(name(a.actor_id))}</strong> ${esc(a.message)}${i?`<button class="issue-link" data-action="open-issue" data-id="${i.id}">${esc(issueKey(i))} · ${esc(i.summary)}</button>`:''}<div class="activity-time">${time(a.created_at)}</div></div></div>`;}).join('')||'<div class="empty inline"><p>Your team’s updates will appear here.</p></div>';}
function activityPage(){return heading('A shared view of <em>what changed.</em>','Every report, fix, and conversation, in one timeline.','','WORKSPACE ACTIVITY')+`<div class="panel activity-page">${activityItems([...data.activity].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)))}</div>`;}
function notificationsPage(){return heading('Stay in <em>the loop.</em>','Updates on reports, assignments, and conversations.',button(icon('check')+' Mark all read','read-all'),'YOUR NOTIFICATIONS')+`<div class="panel">${[...data.notifications].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).map(n=>`<div class="notice-row ${n.read_at?'':'unread'}"><span class="stat-icon">${icon('bell')}</span><div class="notice-content"><p>${esc(n.message)}</p><div class="hint">${time(n.created_at)}</div></div><button class="text-button" data-action="read-notice" data-id="${n.id}">View issue ${icon('arrow')}</button></div>`).join('')||empty('You’re all caught up','Notifications will appear when your team updates reports or adds comments.')}</div>`;}
function settingsPage(){return heading('Make yourself <em>at home.</em>','Your account and workspace connection.','','WORKSPACE SETTINGS')+`<div class="settings-grid"><div class="panel settings-card"><h2>Your account</h2><div class="setting-line"><span class="muted">Name</span><strong>${esc(me.full_name)}</strong></div><div class="setting-line"><span class="muted">Email</span><strong>${esc(me.email)}</strong></div><div class="setting-line"><span class="muted">Role</span><strong>${esc(me.role)}</strong></div><form data-form="password" style="margin-top:24px"><div class="form-error" role="alert"></div><div class="field"><label for="new-password">New password</label><input id="new-password" type="password" name="password" minlength="12" autocomplete="new-password" required><small>Use at least 12 characters.</small></div><button class="btn primary" type="submit">Update password</button></form></div><div class="panel settings-card"><h2>Workspace connection</h2><span class="badge ${repo.demo?'open':'closed'}">${repo.demo?'Demo mode':'Signed in to Supabase'}</span><p>Project data, account access, and screenshots are stored in your Supabase project.</p><div class="field"><label>Project URL</label><div class="prose">${esc(SUPABASE_URL)}</div></div>${button(icon('shield')+' Setup guide','setup')}<p>Need a new project assignment or a different role? Contact your workspace administrator.</p>${repo.demo?button('Reset sample data','reset-demo','danger'):''}</div></div>`;}
function modal(title,body,wide=false,subtitle=''){closeModal(false);lastFocus=document.activeElement;$('#modal-root').innerHTML=`<dialog class="modal ${wide?'wide':''}"><div class="modal-header"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div></dialog>`;const dialog=$('dialog');dialog.addEventListener('close',()=>{if(dialog!==$('dialog'))return;detailId=null;if(location.hash.startsWith('#issue/'))history.replaceState(null,'',`#${view}`);});dialog.showModal();dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});}
function closeModal(clearHash=true){modalToken++;const dialog=$('dialog');if(dialog){dialog.close();$('#modal-root').innerHTML='';lastFocus?.isConnected&&lastFocus.focus();}detailId=null;if(clearHash&&location.hash.startsWith('#issue/'))history.replaceState(null,'',`#${view}`);}
function field(label,name,value='',type='text',attrs=''){const id='f-'+name;return `<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;}
function textarea(label,name,value='',attrs=''){return `<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" ${attrs}>${esc(value)}</textarea></div>`;}
function selectField(label,name,values,value,emptyLabel){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options(values,value,emptyLabel)}</select></div>`;}
const formEnd=(text)=>`<div class="modal-footer">${button('Cancel','close-modal')}<button type="submit" class="btn primary">${text}</button></div>`;
function issueForm(id){const i=data.issues.find(i=>i.id===id)||{},editing=!!i.id;const available=data.projects.filter(p=>!p.archived||p.id===i.project_id);if(!available.length){toast(admin()?'Create a project before reporting an issue.':'You don’t have an active project. Ask your administrator for access.',true);return;}modal(editing?'Edit issue':'Report an issue',`<form data-form="issue" data-id="${i.id||''}"><div class="form-error" role="alert"></div><div class="form-grid">${selectField('Project *','project_id',available.map(p=>[p.id,p.name]),i.project_id||filters.project||available[0].id)}${selectField('Issue type','type',TYPES,i.type||'Bug')}<div class="span-2">${field('Summary *','summary',i.summary,'text','required minlength="3" maxlength="200" placeholder="A short, clear description of the issue"')}</div><div class="span-2">${textarea('Description','description',i.description,'maxlength="30000" placeholder="What happened? Give your team some context."')}</div>${selectField('Priority','priority',PRIORITIES,i.priority||'Medium')}${field('App version','app_version',i.app_version,'text','maxlength="100" placeholder="e.g. 1.4.2"')}<div class="span-2">${textarea('Steps to reproduce','steps',i.steps,'maxlength="15000" placeholder="1. Open the app…\n2. Navigate to…\n3. Observe…"')}</div>${textarea('Expected result','expected',i.expected,'maxlength="15000"')}${textarea('Actual result','actual',i.actual,'maxlength="15000"')}<div class="span-2">${field('Device / browser','device',i.device,'text','maxlength="300" placeholder="e.g. Android 14 · Pixel 7, Chrome 130"')}</div>${!editing?'<div class="field span-2"><label for="screenshots">Screenshots (optional)</label><div class="upload-box"><input id="screenshots" type="file" name="screenshots" accept="image/png,image/jpeg,image/webp,image/gif" multiple></div><small>PNG, JPEG, WebP, or GIF · up to 10 MB each · maximum 5 images</small></div>':''}</div>${formEnd(editing?'Save changes':'Create issue')}</form>`,true);if(editing)$('[name="project_id"]').disabled=true;}
function projectForm(id){if(!admin())return;const p=project(id)||{};modal(p.id?'Manage project':'Create a project',`<form data-form="project" data-id="${p.id||''}"><div class="form-error" role="alert"></div>${field('Project name *','name',p.name,'text','required maxlength="120" placeholder="e.g. Student Portal"')}<div class="form-grid">${field('Issue prefix *','prefix',p.prefix,'text','required pattern="[A-Z][A-Z0-9]{1,7}" maxlength="8" placeholder="e.g. STUD"')}${field('Project color','color',p.color||'#7860dc','color')}</div>${textarea('Description','description',p.description,'maxlength="2000" placeholder="What is this app for?"')}${p.id?`<label class="checkbox-row"><input type="checkbox" name="archived" ${p.archived?'checked':''}><span class="profile-text"><strong>Archive this project</strong><span>Keep its history and stop new reports.</span></span></label>`:''}${p.id?`<div class="actions" style="margin:18px 0">${button(icon('users')+' Manage project access','members','',`data-id="${p.id}"`)}</div>`:'<p class="hint">After creating the project, use “Manage project access” to assign testers and developers.</p>'}${formEnd(p.id?'Save project':'Create project')}</form>`);}
function memberForm(id){if(!admin())return;const p=project(id);const members=data.project_members.filter(m=>m.project_id===id).map(m=>m.user_id);modal('Project access',`<form data-form="members" data-id="${id}"><p class="hint" style="margin:0 0 18px">Choose who can access ${esc(p.name)}. Administrators automatically have access to every project.</p><div class="form-error" role="alert"></div><div class="checkbox-list">${data.profiles.filter(u=>u.role!=='admin').map(u=>`<label class="checkbox-row"><input type="checkbox" name="user_ids" value="${u.id}" ${members.includes(u.id)?'checked':''}>${avatar(u.id)}<span class="profile-text"><strong>${esc(u.full_name)}</strong><span>${esc(u.role)} · ${esc(u.email)}${u.active?'':' · Disabled'}</span></span></label>`).join('')||'<p class="hint">Create tester or developer accounts first.</p>'}</div>${formEnd('Save access')}</form>`,false,esc(p.name));}
function userForm(id){if(!admin())return;const u=person(id)||{};modal(u.id?'Manage team member':'Create a team account',`<form data-form="user" data-id="${u.id||''}"><div class="form-error" role="alert"></div>${u.id?`<div class="member-row" style="margin-bottom:20px">${avatar(u.id)}<div><strong>${esc(u.full_name)}</strong><p class="hint">${esc(u.email)}</p></div></div>`:field('Full name *','full_name','','text','required maxlength="120"')+field('Username *','username','','text','required minlength="3" maxlength="32" autocomplete="off" placeholder="e.g. ananya.rao"')+field('Email address *','email','','email','required autocomplete="off"')+field('Initial password *','password','','password','required minlength="12" autocomplete="new-password"')}<p class="hint">${u.id?'Account access is enforced across the workspace.':'Use a password of at least 12 characters. Share the credentials with this person privately; they can change their password after signing in.'}</p>${selectField('Workspace role','role',[['tester','Tester'],['developer','Developer'],['admin','Administrator']],u.role||'tester')}${u.id?`<label class="checkbox-row"><input type="checkbox" name="active" ${u.active?'checked':''}><span>Account active</span></label>${u.id===me.id?'<p class="hint">Your own administrator role and account status cannot be changed here.</p>':button('Set a new password','reset-user-password','small',`data-id="${u.id}"`)}`:''}${u.id?button('Set username','set-username','small',`data-id="${u.id}"`):''}${formEnd(u.id?'Save member':'Create account')}</form>`);if(u.id===me.id){$('[name="role"]').disabled=true;$('[name="active"]').disabled=true;$('dialog [type="submit"]').disabled=true;}}
function setupGuide(){modal('Connect your workspace',`<p class="prose" style="margin-top:0">Your app is configured with your Supabase URL and publishable key. Finish these steps once to enable live accounts and project data.</p><div class="setup-steps"><div class="setup-step"><strong>Create the database</strong>Open your Supabase project → SQL Editor → New query. Run the database setup first, then the username migration. Run each file once.<br><a href="./workspace.sql" download="001_workspace.sql">Download database setup ↓</a><br><a href="./usernames.sql" download="002_usernames.sql">Download username migration ↓</a></div><div class="setup-step"><strong>Create your administrator account</strong>Go to Authentication → Users → Add user → Create new user. Enter your email and a password, and enable Auto Confirm User. Then run this in SQL Editor, replacing the email:<pre>update public.profiles
set role = 'admin'
where email = 'YOUR_ADMIN_EMAIL';</pre>In Authentication settings, turn off public sign-ups.</div><div class="setup-step"><strong>Enable account creation inside the app</strong>Deploy the included <code>admin-users</code> Edge Function. The project files include its JavaScript source and configuration. It checks the signed-in administrator before creating an account.<pre>supabase login
supabase link --project-ref aywtgapueekmhvyomoyc
supabase functions deploy admin-users\nsupabase functions deploy username-login</pre>These commands run from the downloaded project folder. The server uses Supabase’s built-in server credentials; no secret belongs in the browser.<br><a href="./admin-users.js" download="index.js">Download account-function source ↓</a></div><div class="setup-step"><strong>Sign in and bring your team in</strong>Sign in with your administrator account. Create projects and tester accounts, then open each project’s settings → Manage project access. Testers will only see their assigned projects.</div></div><p class="hint">The published preview is private to you. Before inviting testers, host the frontend at a URL they can visit, or explicitly share the hosted Site with them. Supabase login and project permissions still apply.</p>${button('Got it','close-modal','primary')}`,true);}
async function openIssue(id,tab='discussion'){
 const i=data.issues.find(i=>i.id===id);if(!i){toast('This issue is unavailable or you no longer have access.',true);return;}
 detailTab=tab;modal(esc(issueKey(i)),`<p class="hint">Loading issue…</p>`,true,esc(project(i.project_id)?.name));detailId=id;history.replaceState(null,'',`#issue/${id}`);const token=modalToken;
 try{const details=await repo.details(id);if(token!==modalToken||detailId!==id)return;const urls=await Promise.all(details.attachments.map(async a=>({...a,url:await repo.imageUrl(a)})));if(token!==modalToken||detailId!==id)return;
 const assignees=data.profiles.filter(u=>u.active&&(u.role==='admin'||u.role==='developer'&&data.project_members.some(m=>m.project_id===i.project_id&&m.user_id===u.id)));
 const statuses=developer()?STATUSES:[...new Set([i.status,...(i.status==='Ready for testing'?['Open','Closed']:i.status==='Closed'?['Open']:[])])];
 $('dialog .modal-body').innerHTML=`<div class="detail-summary">${esc(i.summary)}</div><div class="detail-layout"><section class="detail-main"><h3>Description</h3><div class="prose">${esc(i.description||'No description provided.')}</div>${i.steps?'<h3>Steps to reproduce</h3><div class="prose">'+esc(i.steps)+'</div>':''}${i.expected||i.actual?`<div class="form-grid"><div><h3>Expected result</h3><div class="prose">${esc(i.expected||'—')}</div></div><div><h3>Actual result</h3><div class="prose">${esc(i.actual||'—')}</div></div></div>`:''}<h3>Screenshots <span class="hint">${urls.length}</span></h3><div class="attachment-grid">${urls.map(a=>`<div class="attachment"><a href="${esc(a.url)}" target="_blank" rel="noopener"><img src="${esc(a.url)}" alt="${esc(a.name)}"></a><div class="attachment-foot"><span title="${esc(a.name)}">${esc(a.name)}</span>${developer()||a.created_by===me.id?`<button class="icon-button" data-action="remove-attachment" data-id="${a.id}" data-issue="${i.id}" aria-label="Remove ${esc(a.name)}">${icon('trash')}</button>`:''}</div></div>`).join('')}</div><form data-form="attachment" data-id="${i.id}" style="margin-top:12px"><div class="form-error" role="alert"></div><div class="field"><label for="attach-file">Add screenshot</label><input id="attach-file" type="file" name="file" accept="image/png,image/jpeg,image/webp,image/gif" required></div><button class="btn small" type="submit">${icon('plus')} Upload image</button></form>${i.duplicate_of?`<div class="detail-link"><span class="hint">Duplicate of</span><button data-action="open-issue" data-id="${i.duplicate_of}">${esc(data.issues.find(x=>x.id===i.duplicate_of)?issueKey(data.issues.find(x=>x.id===i.duplicate_of)):'Linked issue')}</button></div>`:''}<div class="detail-tabs"><button data-action="detail-tab" data-value="discussion" class="${tab==='discussion'?'active':''}">Discussion (${details.comments.length})</button><button data-action="detail-tab" data-value="activity" class="${tab==='activity'?'active':''}">Activity history</button></div>${tab==='activity'?activityItems(data.activity.filter(a=>a.issue_id===id).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))):details.comments.map(c=>`<div class="comment"><div class="comment-top">${avatar(c.created_by,true)}<strong>${esc(name(c.created_by))}</strong><time>${time(c.created_at)}</time></div><p>${esc(c.body)}</p></div>`).join('')+`<form class="comment-form" data-form="comment" data-id="${id}"><div class="form-error" role="alert"></div>${textarea('Add a comment','body','','required maxlength="10000" placeholder="Share an update or ask a question…"')}<div class="modal-footer"><button class="btn primary small" type="submit">Post comment ${icon('arrow')}</button></div></form>`}</section><aside class="detail-meta"><div><label for="detail-status">Status</label><select id="detail-status" data-issue-change="status" data-id="${id}" ${statuses.length===1?'disabled':''}>${options(statuses,i.status)}</select></div><div><label>Priority</label><div class="meta-value">${priorityBadge(i.priority)}</div></div><div><label for="detail-assignee">Assignee</label><select id="detail-assignee" data-issue-change="assignee_id" data-id="${id}" ${developer()?'':'disabled'}>${options(assignees.map(u=>[u.id,u.full_name]),i.assignee_id,'Unassigned')}</select></div><div><label>Reported by</label><div class="meta-value">${esc(name(i.created_by))}</div></div><div><label>Issue type</label><div class="meta-value">${esc(i.type)}</div></div><div><label>App version</label><div class="meta-value">${esc(i.app_version||'—')}</div></div><div><label>Device / browser</label><div class="meta-value">${esc(i.device||'—')}</div></div><div><label>Created</label><div class="meta-value">${date(i.created_at)}</div></div><div><label>Last updated</label><div class="meta-value">${date(i.updated_at)}</div></div><div class="actions" style="flex-wrap:wrap">${developer()||i.created_by===me.id?button(icon('edit')+' Edit','edit-issue','small',`data-id="${i.id}"`):''}${button(icon('link')+' Copy link','copy-issue','small',`data-id="${i.id}"`)}${developer()?button('Link duplicate','link-duplicate','small',`data-id="${i.id}"`):''}</div></aside></div>`;
 }catch(e){if(token===modalToken)$('dialog .modal-body').innerHTML=`<div class="form-error">${esc(errorText(e))}</div>`;}
}
function navigate(next){view=next;page=1;closeModal();history.replaceState(null,'',`#${next}`);render();window.scrollTo(0,0);}
function route(){const hash=location.hash.slice(1);if(hash.startsWith('issue/')){openIssue(hash.slice(6));return;}if(['dashboard','projects','issues','team','activity','notifications','settings'].includes(hash)){view=hash;render();}}
function downloadCSV(){const list=view==='issues'?filtered():data.issues;const rows=[['Issue ID','Project','Summary','Description','Type','Priority','Status','Assignee','Reporter','Steps to reproduce','Expected','Actual','App version','Device','Created','Updated'],...list.map(i=>[issueKey(i),project(i.project_id)?.name,i.summary,i.description,i.type,i.priority,i.status,i.assignee_id?name(i.assignee_id):'',name(i.created_by),i.steps,i.expected,i.actual,i.app_version,i.device,i.created_at,i.updated_at])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(csvValue).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`GNITS_develop-issues-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Exported ${list.length} issues.`);}
const actions={
 'navigate':b=>navigate(b.dataset.view),
 'menu':()=>$('.sidebar')?.classList.toggle('open'),
 'demo':async()=>{repo=new Repository(true);await repo.init();view='dashboard';filters={project:'',status:'',priority:'',type:'',search:'',mine:false};await enter();},
 'logout':async()=>{await repo.logout();closeModal();repo=new Repository();me=null;data={profiles:[],projects:[],issues:[],project_members:[],activity:[],notifications:[]};history.replaceState(null,'','#');loginScreen();},
 'setup':setupGuide,
 'login-help':()=>modal('Ask your administrator for access',`<p class="prose">Your administrator creates your account and assigns your projects. Ask them for your login email or username, initial password, and project access. If you forgot your password, they can set a new one from Team members → Manage.</p>${button('Got it','close-modal','primary')}`),
 'new-issue':()=>issueForm(), 'edit-issue':b=>issueForm(b.dataset.id), 'new-project':()=>projectForm(), 'edit-project':b=>projectForm(b.dataset.id),'new-user':()=>userForm(),'edit-user':b=>userForm(b.dataset.id),'members':b=>memberForm(b.dataset.id),
 'project-issues':b=>{filters={project:b.dataset.id,status:'',priority:'',type:'',search:'',mine:false};navigate('issues');},
 'close-modal':()=>closeModal(), 'open-issue':b=>openIssue(b.dataset.id), 'detail-tab':b=>openIssue(detailId,b.dataset.value),
 'issue-view':b=>{issueView=b.dataset.value;render();},'clear-filters':()=>{filters={project:'',status:'',priority:'',type:'',search:'',mine:false};page=1;render();},'prev':()=>{page--;render();},'next':()=>{page++;render();},'export':downloadCSV,
 'copy-issue':async b=>{const url=new URL(location.href);url.hash='issue/'+b.dataset.id;try{await navigator.clipboard.writeText(url.href);toast('Issue link copied.');}catch{modal('Issue link',`<p class="hint">Copy this link to share with a project member.</p>${field('Issue URL','url',url.href,'url','readonly')}`);}},
 'link-duplicate':b=>{const i=data.issues.find(i=>i.id===b.dataset.id);modal('Link a duplicate report',`<form data-form="duplicate" data-id="${i.id}"><div class="form-error" role="alert"></div><p class="hint">Choose the original report from the same project.</p>${selectField('Original issue','duplicate_of',data.issues.filter(x=>x.project_id===i.project_id&&x.id!==i.id).map(x=>[x.id,issueKey(x)+' · '+x.summary]),i.duplicate_of,'Not a duplicate')}${formEnd('Save link')}</form>`);},
 'remove-attachment':b=>{modal('Remove screenshot?',`<p class="prose">This permanently removes the selected screenshot.</p><div class="modal-footer">${button('Cancel','close-modal')}${button('Remove screenshot','confirm-remove-attachment','danger',`data-id="${b.dataset.id}" data-issue="${b.dataset.issue}"`)}</div>`);},
 'confirm-remove-attachment':async b=>{const {attachments}=await repo.details(b.dataset.issue);const a=attachments.find(a=>a.id===b.dataset.id);if(!a)throw new Error('Screenshot not found');await repo.removeAttachment(a);await openIssue(b.dataset.issue);toast('Screenshot removed.');},
 'read-all':async()=>{await Promise.all(data.notifications.filter(n=>!n.read_at).map(n=>repo.update('notifications',n.id,{read_at:new Date().toISOString()})));await refresh();toast('All notifications marked as read.');},
 'read-notice':async b=>{const n=data.notifications.find(n=>n.id===b.dataset.id);if(!n.read_at)await repo.update('notifications',n.id,{read_at:new Date().toISOString()});await refresh();if(n.issue_id)await openIssue(n.issue_id);},
 'set-username':b=>modal('Set sign-in username',`<form data-form="username" data-id="${b.dataset.id}"><div class="form-error" role="alert"></div><p class="hint">Username for ${esc(name(b.dataset.id))}. Use 3–32 letters, numbers, dots, underscores, or hyphens. Email sign-in stays available.</p>${field('Username','username',person(b.dataset.id)?.username||'','text','required minlength="3" maxlength="32"')}${formEnd('Save username')}</form>`),
 'reset-user-password':b=>modal('Set a new password',`<form data-form="reset-password" data-id="${b.dataset.id}"><div class="form-error" role="alert"></div><p class="hint">Set a new password for ${esc(name(b.dataset.id))} and share it privately.</p>${field('New password','password','','password','required minlength="12" autocomplete="new-password"')}${formEnd('Set password')}</form>`),
 'reset-demo':()=>modal('Reset demo workspace?',`<p class="prose">This clears demo reports and screenshots saved in this browser. Live Supabase data is unaffected.</p><div class="modal-footer">${button('Cancel','close-modal')}${button('Reset demo','confirm-reset-demo','danger')}</div>`),
 'confirm-reset-demo':async()=>{localStorage.removeItem(DEMO_KEY);await repo.init();closeModal();await refresh();toast('Demo workspace reset.');}
};
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const action=actions[b.dataset.action];if(!action)return;b.disabled=true;try{await action(b);}catch(e){toast(errorText(e),true);}finally{if(b.isConnected)b.disabled=false;}});
document.addEventListener('change',async event=>{const el=event.target;if(el.dataset.filter){filters[el.dataset.filter]=el.type==='checkbox'?el.checked:el.value;page=1;render();return;}if(el.dataset.issueChange){const id=el.dataset.id,key=el.dataset.issueChange,value=el.value;el.disabled=true;try{await repo.update('issues',id,{[key]:value||null});await refresh();await openIssue(id,detailTab);toast('Issue updated.');}catch(e){toast(errorText(e),true);await openIssue(id,detailTab);}}});
document.addEventListener('input',event=>{if(event.target.id==='issue-search'){const el=event.target,start=el.selectionStart;filters.search=el.value;page=1;render();const next=$('#issue-search');next.focus();next.setSelectionRange(start,start);}});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();$('#global-search')?.focus();}});
window.addEventListener('hashchange',()=>{if(me)route();});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!form.dataset.form)return;event.preventDefault();const submit=form.querySelector('[type="submit"]');if(submit?.disabled)return;const original=submit?.innerHTML;if(submit){submit.disabled=true;submit.textContent='Please wait…';}const fd=new FormData(form),values=Object.fromEntries(fd),id=form.dataset.id;
 const err=form.querySelector('.form-error');if(err)err.textContent='';
 try{
  switch(form.dataset.form){
   case 'login':{repo=new Repository();await repo.login(values.identifier.trim(),values.password);await enter();break;}
   case 'search':{filters={project:'',status:'',priority:'',type:'',mine:false,search:values.search.trim()};navigate('issues');break;}
   case 'issue':{
    const selected=project(id?data.issues.find(i=>i.id===id).project_id:values.project_id);if(!selected)throw new Error('Choose a project.');
    const files=fd.getAll('screenshots').filter(f=>f instanceof File&&f.size>0);if(files.length>5)throw new Error('Attach no more than 5 images at once.');for(const f of files)if(!['image/png','image/jpeg','image/webp','image/gif'].includes(f.type)||f.size>10485760)throw new Error('Use supported images up to 10 MB each.');
    const payload={summary:values.summary.trim(),description:values.description.trim(),type:values.type,priority:values.priority,steps:values.steps.trim(),expected:values.expected.trim(),actual:values.actual.trim(),app_version:values.app_version.trim(),device:values.device.trim()};if(payload.summary.length<3)throw new Error('Summary needs at least 3 characters.');
    const issue=id?await repo.update('issues',id,payload):await repo.insert('issues',{...payload,project_id:selected.id,created_by:me.id,status:'Open',assignee_id:null,duplicate_of:null});
    const failures=[];for(const file of files){try{await repo.upload(issue,file);}catch(e){failures.push(file.name+': '+errorText(e));}}
    closeModal();await refresh();await openIssue(issue.id);toast(failures.length?'Issue saved. Some screenshots failed: '+failures.join('; '):id?'Issue saved.':'Issue created.',failures.length>0);break;
   }
   case 'project':{const payload={name:values.name.trim(),prefix:values.prefix.trim().toUpperCase(),description:values.description.trim(),color:values.color,archived:fd.has('archived')};if(!payload.name)throw new Error('Enter a project name.');const p=id?await repo.update('projects',id,payload):await repo.insert('projects',{...payload,created_by:me.id});closeModal();await refresh();toast(id?'Project updated.':'Project created. Assign your team next.');if(!id)memberForm(p.id);break;}
   case 'members':{await repo.memberships(id,fd.getAll('user_ids'));closeModal();await refresh();toast('Project access updated.');break;}
   case 'user':{const payload=id?{action:'update',user_id:id,role:values.role,active:fd.has('active')}:{action:'create',full_name:values.full_name.trim(),username:values.username.trim().toLowerCase(),email:values.email.trim(),password:values.password,role:values.role};await repo.admin(payload);closeModal();await refresh();toast(id?'Team member updated.':'Account created. Share their credentials privately and assign project access.');break;}
   case 'username':{await repo.admin({action:'set-username',user_id:id,username:values.username.trim().toLowerCase()});closeModal();await refresh();toast('Username saved. Use it with the same account password.');break;}
   case 'reset-password':{await repo.admin({action:'reset-password',user_id:id,password:values.password});closeModal();toast(repo.demo?'Password action simulated in demo mode.':'Password updated. Share it privately with the team member.');break;}
   case 'password':{await repo.changePassword(values.password);form.reset();toast(repo.demo?'Password action simulated in demo mode.':'Your password has been updated.');break;}
   case 'comment':{const body=values.body.trim();if(!body)throw new Error('Write a comment first.');await repo.insert('comments',{issue_id:id,body,created_by:me.id});await refresh();await openIssue(id);toast('Comment added.');break;}
   case 'attachment':{if(!values.file?.size)throw new Error('Choose an image first.');await repo.upload(data.issues.find(i=>i.id===id),values.file);await openIssue(id,detailTab);toast('Screenshot uploaded.');break;}
   case 'duplicate':{await repo.update('issues',id,{duplicate_of:values.duplicate_of||null});await refresh();await openIssue(id);toast('Duplicate link updated.');break;}
  }
 }catch(e){if(form.isConnected)errorAt(form,e);else toast(errorText(e),true);}finally{if(submit?.isConnected){submit.disabled=false;submit.innerHTML=original;}}
});
async function boot(){loginScreen();try{const user=await repo.init();if(user)await enter();}catch(e){loginScreen(errorText(e));}}
boot();
// Refresh on return to the tab as well as periodic polling; no Realtime setup is required.
window.addEventListener('focus',()=>{if(me)refresh().catch(e=>toast(errorText(e),true));});
setInterval(()=>{if(me&&!document.hidden)refresh().catch(()=>{});},60000);
